content.text:
{
  "name": "SRS570电流前置放大器",
  "name_en": "SRS570 Current Preamplifier",
  "manufacturer": "Stanford Research Systems",
  "description": "SRS570 是一款电流前置放大器，用于将微弱电流信号放大并转换为便于采集的电压信号。该设备适合实验室中对光电探测器、电化学信号或其他低电流水平传感器进行低噪声读出，并支持灵敏度、偏置、滤波和偏移调节。",
  "description_en": "The SRS570 is a current preamplifier used to amplify very small current signals and convert them into voltages suitable for acquisition. It is used in laboratories for low-noise readout of photodetectors, electrochemical signals, and other low-current sensors, with control over sensitivity, bias, filtering, and offset.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化放大器的偏置、增益模式、滤波类型和反相设置。",
      "description_en": "Initialize the amplifier bias, gain mode, filter type, and inversion setting."
    },
    {
      "action_name": "auto-set_sensitivity",
      "description": "设置电流灵敏度，并可按灵敏度比例调整输入偏移。",
      "description_en": "Set the current sensitivity, with optional scaling of the input offset relative to the selected sensitivity."
    },
    {
      "action_name": "auto-set_offset",
      "description": "设置输入电流偏移量。",
      "description_en": "Set the input current offset."
    },
    {
      "action_name": "auto-increase_sensitivity",
      "description": "将灵敏度提高一个档位。",
      "description_en": "Increase the sensitivity by one step."
    },
    {
      "action_name": "auto-decrease_sensitivity",
      "description": "将灵敏度降低一个档位。",
      "description_en": "Decrease the sensitivity by one step."
    }
  ],
  "tag_hints": [
    "current preamplifier",
    "low-noise current measurement",
    "sensitivity gain control",
    "photodiode readout",
    "signal filtering",
    "bias and offset adjustment"
  ]
}

